      this.charts.patientGaugeChart.setOption(option);
    },
    updatePatientFlowChart() {
      if (!this.charts.patientFlowChart) {
        this.charts.patientFlowChart = echarts.init(this.$refs.patientFlowChart);
      }
      const option = {
        radar: {
          indicator: [{
            name: "医疗质量",
            max: 100
          }, {
            name: "专病治疗",
            max: 100
          }, {
            name: "医疗费用",
            max: 100
          }, {
            name: "患者满意",
            max: 100
          }, {
            name: "服务态度",
            max: 100
          }, {
            name: "环境舒适",
            max: 100
          }],
          shape: "polygon",
          splitNumber: 5,
          axisName: {
            color: "#428BD4"
          },
          splitLine: {
            lineStyle: {
              color: "rgba(66, 139, 212, 0.3)"
            }
          },
          splitArea: {
            show: false
          },
          axisLine: {
            lineStyle: {
              color: "rgba(66, 139, 212, 0.3)"
            }
          }
        },
        series: [{
          name: "患者流量分布",
          type: "radar",
          data: [{
            value: [81, 90, 78, 60, 85, 70],
            name: "实际指标",
            lineStyle: {
              color: "#5CACEE"
            },
            areaStyle: {
              color: "rgba(92, 172, 238, 0.6)"
            }
          }]
        }]
      };
      this.charts.patientFlowChart.setOption(option);
    },
    updateVisitTrendChart() {
      if (!this.charts.visitTrendChart) {
        this.charts.visitTrendChart = echarts.init(this.$refs.visitTrendChart);
      }

      // 生成时间段数据
      const hours = ["00:00", "04:00", "08:00", "12:00", "16:00", "20:00", "24:00"];
      const data = [120, 132, 301, 334, 290, 230, 150];
      const option = {
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "category",
          boundaryGap: false,
          data: hours,
          axisLine: {
            lineStyle: {
              color: "#666"
            }
          }
        },
        yAxis: {
          type: "value",
          axisLine: {
            lineStyle: {
              color: "#666"
            }
          }
        },
        series: [{
          data: data,
          type: "line",
          areaStyle: {
            color: {
              type: "linear",
              x: 0,
              y: 0,
              x2: 0,
              y2: 1,
              colorStops: [{
                offset: 0,
                color: "rgba(58, 132, 255, 0.6)"
              }, {
                offset: 1,
                color: "rgba(58, 132, 255, 0.1)"
              }]
            }
          },
          lineStyle: {
            color: "#3A84FF",
            width: 2
          },
          symbol: "circle",
          symbolSize: 6,
          itemStyle: {
            color: "#3A84FF"
          },
          smooth: true
        }]
      };
      this.charts.visitTrendChart.setOption(option);
    },
    updateWaitingTimeChart() {
      if (!this.charts.waitingTimeChart) {
        this.charts.waitingTimeChart = echarts.init(this.$refs.waitingTimeChart);
      }

      // 生成时间段数据
      const hours = ["00:00", "04:00", "08:00", "12:00", "16:00", "20:00", "24:00"];
      const waitingData = [15, 25, 40, 30, 35, 20, 10];
      const consultingData = [20, 25, 30, 35, 30, 25, 20];
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          }
        },
        legend: {
          data: ["等待时间(分钟)", "诊疗时间(分钟)"],
          right: 10
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "category",
          data: hours,
          axisLine: {
            lineStyle: {
              color: "#666"
            }
          }
        },
        yAxis: {
          type: "value",
          axisLine: {
            lineStyle: {
              color: "#666"
            }
          }
        },
        series: [{
          name: "等待时间(分钟)",
          type: "line",
          data: waitingData,
          lineStyle: {
            color: "#3A84FF",
            width: 2
          },
          symbol: "circle",
          symbolSize: 6,
          itemStyle: {
            color: "#3A84FF"
          },
          smooth: true
        }, {
          name: "诊疗时间(分钟)",
          type: "line",
          data: consultingData,
          lineStyle: {
            color: "#FF6B6B",
            width: 2
          },
          symbol: "circle",
          symbolSize: 6,
          itemStyle: {
            color: "#FF6B6B"
          },
          smooth: true
        }]
      };
      this.charts.waitingTimeChart.setOption(option);
    },
    updateDeptRevenueChart() {
      if (!this.charts.deptRevenueChart) {
        this.charts.deptRevenueChart = echarts.init(this.$refs.deptRevenueChart);
      }
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          }
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "value"
        },
        yAxis: {
          type: "category",
          data: ["眼科门诊", "眼科住院", "专家门诊", "手术科室", "口腔科"]
        },
        series: [{
          name: "收入(万元)",
          type: "bar",
          data: [20788, 13081, 6890, 6455, 3972],
          itemStyle: {
            color: function (params) {
              const colorList = ["#00C0FF", "#2467D2", "#A15BC9", "#5FB878", "#339999"];
              return colorList[params.dataIndex];
            }
          }
        }]
      };
      this.charts.deptRevenueChart.setOption(option);
    },
    updateDeptVisitChart() {
      if (!this.charts.deptVisitChart) {
        this.charts.deptVisitChart = echarts.init(this.$refs.deptVisitChart);
      }
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          }
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "value"
        },
        yAxis: {
          type: "category",
          data: ["儿科", "中医科", "口腔科", "骨科", "五官科"]
        },
        series: [{
          name: "人次",
          type: "bar",
          data: [260, 230, 215, 186, 165],
          itemStyle: {
            color: function (params) {
              const colorList = ["#00C0FF", "#2467D2", "#A15BC9", "#5FB878", "#339999"];
              return colorList[params.dataIndex];
            }
          },
          barWidth: "60%"
        }]
      };
      this.charts.deptVisitChart.setOption(option);
    },
    updateProgressCharts() {
      // 更新门诊占比仪表盘
      if (!this.charts.outpatientProgress) {
        this.charts.outpatientProgress = echarts.init(this.$refs.outpatientProgress);
      }
      this.initProgressChart(this.charts.outpatientProgress, 20, "#5171FD");

      // 更新住院占比仪表盘
      if (!this.charts.inpatientProgress) {
        this.charts.inpatientProgress = echarts.init(this.$refs.inpatientProgress);
      }
      this.initProgressChart(this.charts.inpatientProgress, 10, "#2E9CDB");

      // 更新抗菌药占比仪表盘
      if (!this.charts.antibioticProgress) {
        this.charts.antibioticProgress = echarts.init(this.$refs.antibioticProgress);
      }
      this.initProgressChart(this.charts.antibioticProgress, 6, "#13CEF6");

      // 更新医院收入仪表盘
      if (!this.charts.hospitalRevenueProgress) {
        this.charts.hospitalRevenueProgress = echarts.init(this.$refs.hospitalRevenueProgress);
      }
      this.initProgressChart(this.charts.hospitalRevenueProgress, 19, "#8C61FF");
    },
    initProgressChart(chart, value, color) {
      const option = {
        series: [{
          type: "gauge",
          startAngle: 180,
          endAngle: 0,
          min: 0,
          max: 100,
          splitNumber: 10,
          axisLine: {
            lineStyle: {
              width: 6,
              color: [[value / 100, color], [1, "#E1E1E1"]]
            }
          },
          pointer: {
            show: false
          },
          axisTick: {
            show: false
          },
          splitLine: {
            show: false
          },
          axisLabel: {
            show: false
          },
          detail: {
            show: false
          }
        }]
      };
      chart.setOption(option);
    },
    resetFilter() {
      this.filterForm = {
        timeRange: "30days",
        department: ["outpatient"]
      };
      this.updateCharts();
    }

    // ... 保留其他现有方法 ...
  },
  mounted() {
    // 检查登录状态
    const isLoggedIn = localStorage.getItem("isLoggedIn");
    if (!isLoggedIn) {
      this.$router.push("/login");
    }

    // 初始化图表
    this.$nextTick(() => {
      this.updateCharts();

      // 响应窗口大小变化
      window.addEventListener("resize", () => {
        for (const key in this.charts) {
          if (this.charts[key]) {
            this.charts[key].resize();
          }
        }
      });
    });
  },
  beforeUnmount() {
    // 移除事件监听
    window.removeEventListener("resize", () => {});

    // 销毁图表实例
    for (const key in this.charts) {
      if (this.charts[key]) {
        this.charts[key].dispose();
      }
    }
  }
};
